import{_ as p,a0 as n,w as d,s as l,ao as s,I as i,x as r,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何解壓 tar 文件到不同的目錄中 | LCTT x X-CMD","titleTemplate":false,"description":"如何解壓 tar 文件到不同的目錄中 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解壓 tar 文件到不同的目錄中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解壓 tar 文件到不同的目錄中 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150115 How To Extract a Tar Files To a Different Directory on a Linux or Unix-like Systems","title":"如何解壓 tar 文件到不同的目錄中","tag":"201502","desc":""},"relativePath":"201502/20150115 How To Extract a Tar Files To a Different Directory on a Linux or Unix-like Systems.md","filePath":"[post].md"}'),f={name:"201502/20150115 How To Extract a Tar Files To a Different Directory on a Linux or Unix-like Systems.md"};function m(x,t,c,u,T,b){const a=n("Link");return d(),l("div",null,[t[13]||(t[13]=s(`<h1 id="如何解壓-tar-文件到不同的目錄中" tabindex="-1">如何解壓 tar 文件到不同的目錄中 <a class="header-anchor" href="#如何解壓-tar-文件到不同的目錄中" aria-label="Permalink to “如何解壓 tar 文件到不同的目錄中”">​</a></h1><p>我想要解壓一個tar文件到一個叫/tmp/data的指定目錄。我該如何在Linux或者類Unix的系統中使用tar命令解壓一個tar文件到不同的目錄中？</p><p>你不必使用cd命令切換到其他的目錄並解壓。可以使用下面的語法解壓一個文件：</p><h3 id="語法" tabindex="-1">語法 <a class="header-anchor" href="#語法" aria-label="Permalink to “語法”">​</a></h3><p>典型Unix tar語法：</p><pre><code>tar -xf file.name.tar -C /path/to/directory
</code></pre><p>GNU/tar 語法：</p><pre><code>tar xf file.tar -C /path/to/directory

tar xf file.tar --directory /path/to/directory
</code></pre><h3 id="示例-解壓文件到另一個目錄中" tabindex="-1">示例：解壓文件到另一個目錄中 <a class="header-anchor" href="#示例-解壓文件到另一個目錄中" aria-label="Permalink to “示例：解壓文件到另一個目錄中”">​</a></h3><p>在本例中。我解壓$HOME/etc.backup.tar到/tmp/data目錄中。首先，需要手動創建這個目錄，輸入：</p><pre><code>mkdir /tmp/data
</code></pre><p>要解壓$HOME/etc.backup.tar 到/tmp/data中，輸入：</p><pre><code>tar -xf $HOME/etc.backup.tar -C /tmp/data
</code></pre><p>要看到進度，使用-v選項：</p><pre><code>tar -xvf $HOME/etc.backup.tar -C /tmp/data
</code></pre><p>示例輸出：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2015/01/tar-extract-archive-to-dir.gif" alt="Gif 01: tar Command Extract Archive To Different Directory Command"></p><p><em>Gif 01: tar命令解壓文件到不同的目錄</em></p><p>你也可以指定解壓的文件：</p><pre><code>tar -xvf $HOME/etc.backup.tar file1 file2 file3 dir1 -C /tmp/data
</code></pre><p>要解壓foo.tar.gz（.tgz擴展文件）包到/tmp/bar中，輸入：</p><pre><code>mkdir /tmp/bar
tar -zxvf foo.tar.gz -C /tmp/bar
</code></pre><p>要解壓foo.tar.bz2（.tbz, .tbz2 和 .tb2 擴展文件）包到/tmp/bar中，輸入：</p><pre><code>mkdir /tmp/bar
tar -jxvf foo.tar.bz2  -C /tmp/bar
</code></pre><hr>`,25)),i("p",null,[t[1]||(t[1]=r("via: ",-1)),e(a,{href:"http://www.cyberciti.biz/faq/howto-extract-tar-file-to-specific-directory-on-unixlinux/"},{default:o(()=>[...t[0]||(t[0]=[r("http://www.cyberciti.biz/faq/howto-extract-tar-file-to-specific-directory-on-unixlinux/",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=r("作者：",-1)),e(a,{href:"http://www.cyberciti.biz/tips/about-us"},{default:o(()=>[...t[2]||(t[2]=[r("nixCraft",-1)])]),_:1}),t[6]||(t[6]=r(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:o(()=>[...t[3]||(t[3]=[r("geekpi",-1)])]),_:1}),t[7]||(t[7]=r(" 校對：",-1)),e(a,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[4]||(t[4]=[r("Caroline",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=r("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[r("LCTT",-1)])]),_:1}),t[11]||(t[11]=r(" 原創翻譯，",-1)),e(a,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[r("Linux中國",-1)])]),_:1}),t[12]||(t[12]=r(" 榮譽推出",-1))])])}const _=p(f,[["render",m]]);export{y as __pageData,_ as default};
